// The traps behind every function the port cannot call yet (dread_port.h). The thunks that jump here
// are generated by tools/port_link.py from the whole-program link's undefined symbols: one per
// function with no source, and one per call the link refused to alias because the caller's argument
// classes differ from the definition's. Each loads the function's original address as the argument.

#include "dread_port.h"

#include <cstdio>
#include <cstdlib>

extern "C" void dread_port_missing_function(u64 address) {
    std::fprintf(stderr, "dread: call to a function with no source yet: fn_%llx (see data/functions/)\n",
                 static_cast<unsigned long long>(address));
    std::fflush(stderr);
    std::abort();
}

extern "C" void dread_port_mismatched_call(u64 address) {
    std::fprintf(stderr,
                 "dread: call to fn_%llx through a declaration whose argument classes differ from the definition's"
                 " (class_mismatch in build/port/link/link.json; fix the declaration)\n",
                 static_cast<unsigned long long>(address));
    std::fflush(stderr);
    std::abort();
}

extern "C" void dread_port_missing_import(const char* name) {
    std::fprintf(stderr, "dread: call to an import the port does not define yet: %s (the game's data points at it)\n",
                 name);
    std::fflush(stderr);
    std::abort();
}
